#include <stdio.h>
#include <assert.h>
int main(void) {
    int n;if(scanf("%d",&n)!=1)return 1;
    if(n<0 || n>20){puts("ОШИБКА");return 0;}
    assert(n>=0 && n<=20);printf("%d\n",n*n);
    return 0;
}
